insert into coaches (id, name, avatar_url, title, fip_certification, experience_years, rating, reviews_count, province, club_names, hourly_rate, bio, specialties, available_days, available_hours) values ('0a9ca50f-2346-4d8a-af34-9533346d2f9a', 'استاد مازیار فلاحی', 'https://images.unsplash.com/photo-1560250097-0b93528c311a?w=300&auto=format&fit=crop&q=80', 'سرمربی بین‌المللی و مدرس رسمی FIP', 'مدرک بین‌المللی FIP Level 2 اسلواکی و اسپانیا', 9, 4.96, 84, 'تهران', ARRAY['باشگاه پدل انقلاب تهران','باشگاه پدل شاهین پاسداران'], 950000, 'تمرکز بر اصول حرفه‌ای بازی شیشه، ضربات Bandeja و Vibora، تصحیح زاویه ایستادن و ساخت تاکتیک تیمی زوج‌های پدل. سابقه هدایت قهرمانان کشوری.', ARRAY['اصلاح تکنیک پایه','استراتژی و حرکت با شیشه','اسمش و والی سرعتی','آماده‌سازی مسابقات'], ARRAY['شنبه','دوشنبه','چهارشنبه','جمعه'], ARRAY['۰۸:۰۰','۰۹:۳۰','۱۶:۰۰','۱۷:۳۰','۱۹:۰۰']);
insert into coaches (id, name, avatar_url, title, fip_certification, experience_years, rating, reviews_count, province, club_names, hourly_rate, bio, specialties, available_days, available_hours) values ('74750bdd-fe89-43e9-bbd3-bd9ec4551a34', 'کاپیتان پریسا شریفی', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=300&auto=format&fit=crop&q=80', 'مربی اسبق تیم ملی پدل و قهرمان لیگ برتر', 'مدرک مربیگری درجه ۱ فدراسیون و آکادمی مادرید', 7, 4.92, 65, 'تهران', ARRAY['باشگاه پدل شاهین پاسداران','مجموعه پدل درکه'], 850000, 'متخصص در افزایش اعتماد به نفس در دفاع، بازی خوانی و ریتم ضربات. برگزاری کلینیک‌های ویژه بانوان و دونفره‌های هماهنگ.', ARRAY['دفاع و دیوار شیشه‌ای','کلینیک دونفره هماهنگ','آمادگی جسمانی اختصاصی پدل','تاکتیک ضد حمله'], ARRAY['یک‌شنبه','سه‌شنبه','پنج‌شنبه'], ARRAY['۰۹:۰۰','۱۰:۳۰','۱۵:۰۰','۱۶:۳۰','۱۸:۰۰']);
insert into coaches (id, name, avatar_url, title, fip_certification, experience_years, rating, reviews_count, province, club_names, hourly_rate, bio, specialties, available_days, available_hours) values ('ffcace79-1b70-4934-8eff-dc80ed2fa4db', 'سامان یزدانی', 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=300&auto=format&fit=crop&q=80', 'مربی رسمی و سرپرست آکادمی اسپادانا', 'مدرک مربیگری پدل فدراسیون بین‌المللی FIP', 5, 4.88, 47, 'اصفهان', ARRAY['آکادمی پدل اسپادانا اصفهان','مجموعه پرواز'], 750000, 'رویکرد تحلیلی به پدل مدرن، آنالیز ویدیویی ضربات شاگردان، برنامه‌ریزی تمرینات پرتاب توپ و موقعیت‌سنجی هوشمندانه در زمین.', ARRAY['آنالیز تصویری بازی','شات‌سلکشن (Shot Selection)','سرویس و ریترن تهاجمی'], ARRAY['شنبه','سه‌شنبه','چهارشنبه','جمعه'], ARRAY['۰۸:۳۰','۱۰:۰۰','۱۷:۰۰','۱۸:۳۰','۲۰:۰۰']);
insert into coaches (id, name, avatar_url, title, fip_certification, experience_years, rating, reviews_count, province, club_names, hourly_rate, bio, specialties, available_days, available_hours) values ('1999c3ec-eb79-4405-966b-d03e23639df8', 'مهرشاد کیان‌پور', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=300&auto=format&fit=crop&q=80', 'مربی آکادمی مارینا کیش و متخصص استعدادیابی', 'مدرک مربیگری پیشرفته FIP Level 1', 6, 4.9, 52, 'هرمزگان', ARRAY['مجموعه بین‌المللی پدل مارینا کیش'], 850000, 'تجربه سال‌ها تمرین در آب‌وهوای ساحلی، بهینه‌سازی تنفس، بازی سرعتی نزدیک تور و آموزش تکنیک‌های پرطرفدار Bajada و Rulo.', ARRAY['ضربات نمایشی و کاربردی','کلینیک فشرده مسافرین کیش','قدرت و سرعت عکس‌العمل'], ARRAY['همه‌روزه'], ARRAY['۰۸:۰۰','۰۹:۳۰','۱۸:۰۰','۱۹:۳۰','۲۱:۰۰']);
